import{_ as a,o as i,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"云备份说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/06-cloud-backup-guide.md","filePath":"v1/zh/guide/06-cloud-backup-guide.md"}'),t={name:"v1/zh/guide/06-cloud-backup-guide.md"};function e(n,l,s,h,u,g){return i(),o("div",null,[...l[0]||(l[0]=[r('<h1 id="云备份说明" tabindex="-1">云备份说明 <a class="header-anchor" href="#云备份说明" aria-label="Permalink to &quot;云备份说明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉记账提供云备份功能，让您可以将账单数据安全地备份到云端，并在多设备间同步。本指南将帮助您了解如何使用云备份功能。</p><hr><h2 id="☁️-什么是云备份" tabindex="-1">☁️ 什么是云备份？ <a class="header-anchor" href="#☁️-什么是云备份" aria-label="Permalink to &quot;☁️ 什么是云备份？&quot;">​</a></h2><p><strong>云备份</strong>是将您的账单数据上传到云端服务器，实现：</p><ul><li><strong>数据安全</strong>：防止设备丢失或损坏导致数据丢失</li><li><strong>多设备同步</strong>：在不同设备上登录同一账号，数据自动同步</li><li><strong>数据恢复</strong>：可以随时从云端恢复数据到新设备</li></ul><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>云备份需要登录账号（目前支持苹果账号登录）</li><li>云端会进行访问控制与数据隔离，只有登录账号的用户才能访问自己的数据</li><li>大部分情况下会自动同步，您也可以在设置页手动触发同步</li></ul></blockquote><hr><h2 id="🔐-登录账号" tabindex="-1">🔐 登录账号 <a class="header-anchor" href="#🔐-登录账号" aria-label="Permalink to &quot;🔐 登录账号&quot;">​</a></h2><h3 id="使用苹果账号登录" tabindex="-1">使用苹果账号登录 <a class="header-anchor" href="#使用苹果账号登录" aria-label="Permalink to &quot;使用苹果账号登录&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面顶部，点击用户信息卡片</li><li>如果未登录，会显示登录选项</li><li>点击 <strong>&quot;使用苹果账号登录&quot;</strong></li><li>按照提示完成苹果账号登录流程</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>登录后，您的数据会自动开始同步到云端</li><li>首次登录可能需要一些时间完成初始同步</li><li>请确保网络连接正常</li></ul></blockquote><hr><h2 id="🔄-云同步机制" tabindex="-1">🔄 云同步机制 <a class="header-anchor" href="#🔄-云同步机制" aria-label="Permalink to &quot;🔄 云同步机制&quot;">​</a></h2><h3 id="自动同步" tabindex="-1">自动同步 <a class="header-anchor" href="#自动同步" aria-label="Permalink to &quot;自动同步&quot;">​</a></h3><p>系统会在以下时机自动同步数据：</p><ul><li><strong>App 启动时</strong>：自动同步账户和账本数据</li><li><strong>数据变更后</strong>：创建、修改、删除账单后自动标记为待同步</li><li><strong>切换账本时</strong>：会静默同步当前账本的数据（如账单、分类、标签等）</li></ul><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>自动同步是后台进行的，不会影响正常使用</li><li>如果网络不可用，数据会暂存在本地，待网络恢复后自动同步</li></ul></blockquote><h3 id="手动同步" tabindex="-1">手动同步 <a class="header-anchor" href="#手动同步" aria-label="Permalink to &quot;手动同步&quot;">​</a></h3><p>您也可以手动触发同步：</p><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面右上角，点击云同步图标（云朵图标）</li><li>等待同步完成（会显示同步进度）</li></ol><blockquote><p>⚠️ <strong>注意</strong>：</p><ul><li>手动同步需要登录账号</li><li>如果未登录，会提示&quot;请先登录后再进行云同步&quot;</li><li>同步过程中请保持 App 在前台运行</li></ul></blockquote><hr><h2 id="📊-同步内容" tabindex="-1">📊 同步内容 <a class="header-anchor" href="#📊-同步内容" aria-label="Permalink to &quot;📊 同步内容&quot;">​</a></h2><h3 id="同步的数据类型" tabindex="-1">同步的数据类型 <a class="header-anchor" href="#同步的数据类型" aria-label="Permalink to &quot;同步的数据类型&quot;">​</a></h3><p>云备份会同步以下数据：</p><ul><li><strong>账本数据</strong>：账本名称、描述、货币、图标等</li><li><strong>账单数据</strong>：所有账单记录（包括金额、分类、标签、备注等）</li><li><strong>账户数据</strong>：账户名称、余额、类型等</li><li><strong>分类数据</strong>：支出和收入分类</li><li><strong>标签数据</strong>：标签组和标签</li></ul><h3 id="不同步的数据" tabindex="-1">不同步的数据 <a class="header-anchor" href="#不同步的数据" aria-label="Permalink to &quot;不同步的数据&quot;">​</a></h3><p>以下数据不会同步到云端：</p><ul><li><strong>App 设置</strong>：主题、语言等本地设置</li><li><strong>缓存数据</strong>：临时缓存数据</li><li><strong>用户偏好</strong>：个人偏好设置</li></ul><hr><h2 id="🔒-数据安全" tabindex="-1">🔒 数据安全 <a class="header-anchor" href="#🔒-数据安全" aria-label="Permalink to &quot;🔒 数据安全&quot;">​</a></h2><h3 id="数据加密" tabindex="-1">数据加密 <a class="header-anchor" href="#数据加密" aria-label="Permalink to &quot;数据加密&quot;">​</a></h3><ul><li><strong>访问控制</strong>：只有登录账号的用户才能访问自己的数据</li><li><strong>数据隔离</strong>：不同账号的数据互相隔离，互不可见</li><li><strong>安全建议</strong>：请妥善保管您的 Apple 账号，并在稳定网络环境下进行首次同步</li></ul><h3 id="数据隔离" tabindex="-1">数据隔离 <a class="header-anchor" href="#数据隔离" aria-label="Permalink to &quot;数据隔离&quot;">​</a></h3><ul><li><strong>用户隔离</strong>：每个用户的数据完全隔离，互不可见</li><li><strong>设备隔离</strong>：不同设备的数据通过用户账号关联</li><li><strong>账本隔离</strong>：不同账本的数据独立存储</li></ul><hr><h2 id="🔄-同步流程" tabindex="-1">🔄 同步流程 <a class="header-anchor" href="#🔄-同步流程" aria-label="Permalink to &quot;🔄 同步流程&quot;">​</a></h2><h3 id="增量同步" tabindex="-1">增量同步 <a class="header-anchor" href="#增量同步" aria-label="Permalink to &quot;增量同步&quot;">​</a></h3><p>考拉记账采用增量同步机制：</p><ul><li><strong>只同步变更</strong>：只同步新增、修改、删除的数据</li><li><strong>提高效率</strong>：减少数据传输量，提高同步速度</li><li><strong>节省流量</strong>：特别适合移动网络环境</li></ul><h3 id="同步状态" tabindex="-1">同步状态 <a class="header-anchor" href="#同步状态" aria-label="Permalink to &quot;同步状态&quot;">​</a></h3><p>每条数据都有同步状态：</p><ul><li><strong>已同步（0）</strong>：数据已成功同步到云端</li><li><strong>待同步（1）</strong>：数据有变更，等待同步</li><li><strong>待删除（2）</strong>：数据已删除，等待同步删除操作</li></ul><h3 id="冲突处理" tabindex="-1">冲突处理 <a class="header-anchor" href="#冲突处理" aria-label="Permalink to &quot;冲突处理&quot;">​</a></h3><p>如果多设备同时修改同一条数据：</p><ul><li><strong>本地优先</strong>：如果本地还有未同步的修改，系统会优先保留本地修改，避免被云端数据覆盖</li><li><strong>以最新修改为准</strong>：当两端同时修改同一条数据时，系统会尽量以最近一次修改为准</li><li><strong>手动解决</strong>：如果出现冲突，可能需要手动解决</li></ul><hr><h2 id="📱-多设备同步" tabindex="-1">📱 多设备同步 <a class="header-anchor" href="#📱-多设备同步" aria-label="Permalink to &quot;📱 多设备同步&quot;">​</a></h2><h3 id="设备要求" tabindex="-1">设备要求 <a class="header-anchor" href="#设备要求" aria-label="Permalink to &quot;设备要求&quot;">​</a></h3><ul><li><strong>登录同一账号</strong>：所有设备必须登录同一个账号</li><li><strong>网络连接</strong>：需要网络连接才能同步</li><li><strong>App 版本</strong>：建议使用最新版本的 App</li></ul><h3 id="同步步骤" tabindex="-1">同步步骤 <a class="header-anchor" href="#同步步骤" aria-label="Permalink to &quot;同步步骤&quot;">​</a></h3><ol><li><p><strong>在新设备上登录</strong>：</p><ul><li>打开考拉记账 App</li><li>使用相同的苹果账号登录</li><li>系统会自动开始同步数据</li></ul></li><li><p><strong>等待同步完成</strong>：</p><ul><li>首次同步可能需要一些时间</li><li>可以在设置页面查看同步状态</li><li>同步完成后，数据会显示在新设备上</li></ul></li><li><p><strong>继续使用</strong>：</p><ul><li>同步完成后，可以在新设备上正常使用</li><li>数据变更会自动同步到其他设备</li></ul></li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建议在同步完成前不要进行大量操作</li><li>如果同步失败，可以手动触发同步</li><li>确保所有设备都登录了同一账号</li></ul></blockquote><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-云备份需要付费吗" tabindex="-1">Q1：云备份需要付费吗？ <a class="header-anchor" href="#q1-云备份需要付费吗" aria-label="Permalink to &quot;Q1：云备份需要付费吗？&quot;">​</a></h3><p><strong>A：</strong> 目前云备份功能是免费的。但未来可能会推出会员功能，提供更多存储空间或高级功能。</p><h3 id="q2-数据会占用多少存储空间" tabindex="-1">Q2：数据会占用多少存储空间？ <a class="header-anchor" href="#q2-数据会占用多少存储空间" aria-label="Permalink to &quot;Q2：数据会占用多少存储空间？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li>普通用户的账单数据通常很小（几 MB 到几十 MB）</li><li>如果数据量很大，可能会影响同步速度</li><li>建议定期清理不需要的数据</li></ul><h3 id="q3-可以关闭云备份吗" tabindex="-1">Q3：可以关闭云备份吗？ <a class="header-anchor" href="#q3-可以关闭云备份吗" aria-label="Permalink to &quot;Q3：可以关闭云备份吗？&quot;">​</a></h3><p><strong>A：</strong> 可以。如果您不想使用云备份：</p><ul><li>不登录账号即可（数据只存储在本地）</li><li>但这样无法在多设备间同步</li><li>也无法防止数据丢失</li></ul><h3 id="q4-同步失败怎么办" tabindex="-1">Q4：同步失败怎么办？ <a class="header-anchor" href="#q4-同步失败怎么办" aria-label="Permalink to &quot;Q4：同步失败怎么办？&quot;">​</a></h3><p><strong>A：</strong> 可以尝试：</p><ol><li>检查网络连接是否正常</li><li>检查是否已登录账号</li><li>手动触发同步</li><li>如果仍然失败，可以稍后重试</li></ol><h3 id="q5-可以恢复历史数据吗" tabindex="-1">Q5：可以恢复历史数据吗？ <a class="header-anchor" href="#q5-可以恢复历史数据吗" aria-label="Permalink to &quot;Q5：可以恢复历史数据吗？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li>已同步到云端的数据会在您登录同一账号后同步到新设备</li><li>如果设备数据丢失，可以从云端恢复</li><li>删除的数据通常无法在 App 内恢复，请谨慎操作</li></ul><h3 id="q6-同步会影响性能吗" tabindex="-1">Q6：同步会影响性能吗？ <a class="header-anchor" href="#q6-同步会影响性能吗" aria-label="Permalink to &quot;Q6：同步会影响性能吗？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li>同步是后台进行的，不会明显影响性能</li><li>大量数据同步可能需要一些时间</li><li>建议在 Wi-Fi 环境下进行首次同步</li></ul><h3 id="q7-可以同步到多个账号吗" tabindex="-1">Q7：可以同步到多个账号吗？ <a class="header-anchor" href="#q7-可以同步到多个账号吗" aria-label="Permalink to &quot;Q7：可以同步到多个账号吗？&quot;">​</a></h3><p><strong>A：</strong> 不可以。每个设备只能登录一个账号，数据只能同步到一个账号。</p><h3 id="q8-卸载-app-后数据会丢失吗" tabindex="-1">Q8：卸载 App 后数据会丢失吗？ <a class="header-anchor" href="#q8-卸载-app-后数据会丢失吗" aria-label="Permalink to &quot;Q8：卸载 App 后数据会丢失吗？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li>如果已登录并同步，数据会保留在云端</li><li>重新安装 App 并登录后，可以恢复数据</li><li>如果未登录，卸载 App 会导致本地数据丢失</li></ul><hr><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>定期同步</strong>：建议定期手动同步，确保数据最新</li><li><strong>网络环境</strong>：首次同步建议在 Wi-Fi 环境下进行</li><li><strong>数据备份</strong>：重要数据建议定期导出备份（CSV/Excel）</li><li><strong>账号安全</strong>：保护好登录账号，避免账号被盗</li><li><strong>多设备管理</strong>：如果使用多设备，建议定期检查同步状态</li></ol><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><ol><li><strong>登录要求</strong>：云备份需要登录账号，未登录无法使用</li><li><strong>网络依赖</strong>：同步需要网络连接，离线时无法同步</li><li><strong>数据安全</strong>：虽然数据已加密，但仍需保护好登录账号</li><li><strong>同步延迟</strong>：同步可能有延迟，不是实时的</li><li><strong>数据恢复</strong>：删除的数据无法恢复，请谨慎操作</li></ol><hr><p><strong>最后更新</strong>：2026年5月</p>',87)])])}const q=a(t,[["render",e]]);export{p as __pageData,q as default};
